package formal

import (
	"errors"
	"fmt"
	"time"
)

// SessionID identifies one client connection to the coordination service.
//
// A session is backed by a lease. When the lease expires, or when the
// connection is lost, the session and all locks owned by it are invalidated.
type SessionID uint64

// RequestID is generated by the client and used to make queue operations
// idempotent across retries.
type RequestID uint64

// Token is a fencing token assigned by the coordination service when a lock
// changes ownership. Tokens are globally monotonic and are never reused.
//
// A fencing token is only meaningful when it is checked by the protected
// resource. The resource must remember the greatest token it has accepted and
// reject every token that is not strictly greater.
type Token uint64

func (t Token) String() string {
	return fmt.Sprintf("%d", uint64(t))
}

// EventType describes a notification sent from the coordination service to a
// client.
type EventType uint8

const (
	// EventGranted reports that a queued request now owns the lock.
	EventGranted EventType = iota + 1
	// EventRevoked reports that an owned lock was revoked. This happens when
	// its session loses its lease or its connection.
	EventRevoked
	// EventSessionLost reports that the session is no longer valid. No new
	// acquisition may be submitted until the client reconnects.
	EventSessionLost
)

func (t EventType) String() string {
	switch t {
	case EventGranted:
		return "granted"
	case EventRevoked:
		return "revoked"
	case EventSessionLost:
		return "session-lost"
	default:
		return fmt.Sprintf("event(%d)", uint8(t))
	}
}

// Event is an at-least-once notification. A transport is allowed to deliver
// the same Event more than once, in any order, including after the session has
// moved on. Client.Deliver is idempotent and ignores stale events.
type Event struct {
	Type     EventType
	Session  SessionID
	Lock     string
	Request  RequestID
	Sequence uint64
	Token    Token

	// Reentrant is true when the grant only increased the recursion depth of
	// an already-owned lock. Reentrant grants carry the existing token.
	Reentrant bool
	Depth     int

	// Err carries the reason for EventSessionLost.
	Err error
}

// Backend is the narrow coordination-service surface consumed by Client.
//
// Implementations must provide these guarantees:
//
//   - Requests are ordered by a service-assigned, strictly increasing
//     sequence number and the queue is FIFO.
//   - Every ownership grant receives a fresh, strictly increasing Token.
//   - An expired or disconnected session loses every lock it owns, and all of
//     its queued requests are removed.
//   - Notifications are at-least-once and may be duplicated.
//
// The sequence and token counters must survive service restarts. Resetting
// either counter could make an old token valid again.
//
// Coordinator is an in-memory Backend suitable for tests and single-process
// integrations.
type Backend interface {
	// OpenSession creates a leased session. notify is used for all events
	// belonging to that session.
	OpenSession(ttl time.Duration, notify func(Event)) (SessionID, error)

	// KeepAlive renews the session lease.
	KeepAlive(session SessionID) error

	// CloseSession releases the session and revokes its locks. It is
	// idempotent.
	CloseSession(session SessionID) error

	// Acquire appends a request to the FIFO queue for lock. It returns the
	// service-assigned sequence number. A grant is reported through notify.
	Acquire(session SessionID, request RequestID, lock string) (sequence uint64, err error)

	// Cancel withdraws a queued request. If the request was already granted,
	// the grant is released. This closes the race between lease expiry and a
	// client-side context cancellation.
	Cancel(session SessionID, request RequestID) error

	// Release releases one recursion level of a lock owned by session. A
	// stale token must not release a newer owner.
	Release(session SessionID, lock string, token Token) error
}

var (
	// ErrClosed reports use of a closed client or service.
	ErrClosed = errors.New("formal: closed")

	// ErrSessionLost is the umbrella error for an invalid session.
	ErrSessionLost = errors.New("formal: session lost")

	// ErrDisconnected reports that no live session is available. New lock
	// requests are refused while a client is disconnected.
	ErrDisconnected = fmt.Errorf("%w: connection is down", ErrSessionLost)

	// ErrLeaseExpired reports that the service expired the session lease.
	ErrLeaseExpired = fmt.Errorf("%w: lease expired", ErrSessionLost)

	// ErrLockLost reports that a handle no longer represents live ownership.
	ErrLockLost = errors.New("formal: lock ownership lost")

	// ErrHandleReleased reports a second Unlock on the same handle.
	ErrHandleReleased = errors.New("formal: handle already released")

	// ErrNotHeld reports that the session does not own the lock.
	ErrNotHeld = errors.New("formal: lock not held")

	// ErrStaleToken reports a release or write carrying an obsolete token.
	ErrStaleToken = errors.New("formal: stale fencing token")

	// ErrAlreadyConnected reports a redundant Reconnect call.
	ErrAlreadyConnected = errors.New("formal: session already connected")

	// ErrInvalidLock reports an empty lock name.
	ErrInvalidLock = errors.New("formal: lock name must not be empty")

	// ErrInvalidTTL reports a non-positive lease duration.
	ErrInvalidTTL = errors.New("formal: ttl must be positive")

	// ErrInvalidCallback reports a nil event callback.
	ErrInvalidCallback = errors.New("formal: event callback must not be nil")

	// ErrInvalidRequest reports a zero request id.
	ErrInvalidRequest = errors.New("formal: request id must be positive")

	// ErrDuplicateRequest reports reuse of a request id for another lock.
	ErrDuplicateRequest = errors.New("formal: request id reused for another lock")

	// ErrTokenExhausted reports that the monotonic token space is exhausted.
	ErrTokenExhausted = errors.New("formal: fencing token space exhausted")
)
